{
  "predictors": [
    {
      "name": "Social Media Sentiment Score",
      "construction": "Aggregate positive and negative sentiment from social media mentions of a firm over the past month using natural language processing techniques.",
      "rationale": "Firms with more positive sentiment may experience increased investor interest and demand, driving up future returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Employee Satisfaction Index",
      "construction": "Average employee satisfaction score from company reviews on platforms like Glassdoor over the past year.",
      "rationale": "Higher employee satisfaction can lead to better productivity and innovation, potentially increasing firm profitability and stock returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Patent Citation Growth",
      "construction": "Year-over-year growth rate in the number of citations received by a firm's patents.",
      "rationale": "Firms with rapidly growing patent citations may be at the forefront of innovation, leading to competitive advantages and higher future returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supply Chain Risk Exposure",
      "construction": "Proportion of a firm's suppliers located in regions with high geopolitical risk, as reported in supply chain disclosures.",
      "rationale": "Firms with higher exposure to risky supply chains may face disruptions, negatively impacting future returns.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Environmental Violation Penalties",
      "construction": "Total monetary penalties paid for environmental violations over the past three years, scaled by firm size.",
      "rationale": "Firms with fewer environmental penalties may have better risk management practices, leading to more stable and higher future returns.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Customer Concentration Ratio",
      "construction": "Percentage of total revenue derived from the firm's top three customers, as reported in financial statements.",
      "rationale": "Firms with lower customer concentration may have more diversified revenue streams, reducing risk and potentially increasing returns.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "R&D Efficiency Ratio",
      "construction": "Ratio of revenue growth to R&D expenditure growth over the past five years.",
      "rationale": "Firms that efficiently convert R&D spending into revenue growth may have superior innovation capabilities, leading to higher future returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Insider Trading Volume",
      "construction": "Total volume of insider purchases minus sales over the past six months, scaled by total shares outstanding.",
      "rationale": "Increased insider buying may signal confidence in the firm's future prospects, predicting higher future returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Board Diversity Index",
      "construction": "Proportion of board members from diverse backgrounds, including gender and ethnicity, as reported in corporate governance disclosures.",
      "rationale": "Diverse boards may offer a wider range of perspectives and better decision-making, potentially enhancing firm performance and returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Product Recall Frequency",
      "construction": "Number of product recalls issued by the firm over the past three years, scaled by total number of products.",
      "rationale": "Firms with fewer product recalls may have better quality control and brand reputation, leading to higher future returns.",
      "higher_returns_for": "low values of the measure"
    }
  ]
}
